CREATE TABLE IF NOT EXISTS public.collections (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, name text NOT NULL, active boolean DEFAULT true, sort_order integer DEFAULT 0, branch_id uuid REFERENCES public.branches(id) ON DELETE CASCADE, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL); CREATE TABLE IF NOT EXISTS public.collection_products (collection_id uuid REFERENCES public.collections(id) ON DELETE CASCADE, product_id uuid REFERENCES public.products(id) ON DELETE CASCADE, sort_order integer DEFAULT 0, PRIMARY KEY(collection_id, product_id));
